    g.fillRect(0, toPx(r - ROAD_W / 2 + 0.4), 2048, 2);
    g.fillRect(0, toPx(r + ROAD_W / 2 - 0.4), 2048, 2);
  }
  // Sidewalk blocks: mid ring, dark inner yard where buildings stand.
  for (const bx of BLOCK_CENTERS) {
    for (const bz of BLOCK_CENTERS) {
      const half = 34;
