  g.fillStyle = 'rgba(230,230,230,0.75)';
  for (const rx of ROADS) {
    for (const rz of ROADS) {
      for (let i = -2; i <= 2; i += 1) {
        g.fillRect(toPx(rx + i * 2.2) - 3, toPx(rz - ROAD_W / 2 - 2), 6, 4 * PX_PER_M);
        g.fillRect(toPx(rx + i * 2.2) - 3, toPx(rz + ROAD_W / 2 - 2), 6, 4 * PX_PER_M);
